const inputData = $input.item.json.output || $input.item.json.text || "";

// --- كود حساب عدد الأسطر التلقائي ---
let rowCount = 0;
try {
    const sheetsData = $("Get Row(s) in sheet5").all();
    rowCount = sheetsData.length;
} catch (e) {
    rowCount = 5; 
}
const uniqueId = rowCount + 1; 

const today = new Date();
const currentDate = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;

let parsedData = {};

try {
    if (typeof inputData === 'object' && inputData !== null) {
        parsedData = inputData;
    } else if (typeof inputData === 'string') {
        let cleanText = inputData.replace(/```json/g, '').replace(/```/g, '').trim();
        parsedData = JSON.parse(cleanText);
    }

    let emailStatus = parsedData.send_email === true || parsedData.send_email === "true";
    const currentAction = parsedData.action_type || "unclear";

    let finalClassification = parsedData.Classification || parsedData.classification || (parsedData.decision_data ? (parsedData.decision_data.Classification || parsedData.decision_data.classification) : null);
    if (!finalClassification && currentAction === "analyze") {
        const fullTextContext = (parsedData.decision || "") + " " + (parsedData.description || "");
        finalClassification = (fullTextContext.includes("LinkedIn") || fullTextContext.includes("مشروع")) ? "تطوير مهني" : "عام";
    }

    let finalTime = parsedData.time || (parsedData.decision_data ? parsedData.decision_data.time : null) || currentDate;

    return [{
        json: {
            id: uniqueId,
            action_type: currentAction,
            delete_search_term: parsedData.delete_search_term || null,
            send_email: emailStatus,
            decision_id: parsedData.decision_id || null,
            success_rate: parsedData.success_rate || null,
            decision: parsedData.decision_data ? parsedData.decision_data.decision : (parsedData.decision || null),
            classification: finalClassification,
            time: finalTime, 
            priority: parsedData.decision_data ? parsedData.decision_data.priority : (parsedData.priority || null),
            description: parsedData.decision_data ? parsedData.decision_data.description : (parsedData.description || null),
            // تمرير حقول الشيت الثانية الجديدة
            best_case: parsedData.best_case || null,
            worst_case: parsedData.worst_case || null,
            mitigation_plan: parsedData.mitigation_plan || null
        }
    }];
} catch (error) {
    return [{ json: { id: uniqueId, action_type: "unclear", send_email: false, time: currentDate, error: "فشل التحليل: " + error.message } }];
}

